 rows.push(['Emergency reserve',base*.1]);const end=endDate(s.start,s.months),days=day(end)-day(s.start),elapsed=Math.min(days,Math.max(0,day(now)-day(s.start))),remainingDays=Math.max(0,days-elapsed),before=now<s.start,ended=now>=end;
 const valid=s.expenses.filter(e=>e.date>=s.start&&e.date<end&&e.date<=now),spent=valid.reduce((a,e)=>a+e.amount,0),fixedSpent=valid.filter(e=>['Housing','Transport'].includes(e.category)).reduce((a,e)=>a+e.amount,0),flexSpent=spent-fixedSpent,fixedTotal=(rent+c.transit)*s.months;
